package android.os;import java.util.*;import java.util.concurrent.*;public class Handler {private static final Queue<Runnable> queue=new ConcurrentLinkedQueue<>();public static final Map<Runnable,Long> delayed=new ConcurrentHashMap<>();public Handler(Looper l){}public boolean post(Runnable r){queue.add(r);return true;}public boolean postDelayed(Runnable r,long d){delayed.put(r,d);return true;}public void removeCallbacks(Runnable r){delayed.remove(r);queue.remove(r);}public static void drain(){Runnable r;while((r=queue.poll())!=null)r.run();}}
